def check_condition(n):
    """Checks if k^2 === 1 (mod n) for all k such that gcd(k, n) = 1."""
    if n < 2:
        return False

    # We only need to check k up to n-1
    for k in range(1, n):
        import math
        if math.gcd(k, n) == 1:
            if (k * k - 1) % n != 0:
                print(f"n={n} failed: k={k}. {k}^2 - 1 = {k*k - 1}, which is not divisible by {n}.")
                return False
    return True

candidates = [2, 3, 4, 6, 8, 12, 24]
results = {}
for n in candidates:
    if check_condition(n):
        results[n] = True
    else:
        results[n] = False

print("Verification results:")
for n, passed in results.items():
    print(f"n={n} passed: {passed}")
